from flask import Flask, request, redirect, session, abort, jsonify
import hashlib
import hmac
import re
import os
import urllib.parse
from functools import wraps

app = Flask(__name__)
# Load secret key from a secure source (environment variable / secrets manager).
# Fail closed if it is not configured rather than falling back to a hardcoded value.
app.secret_key = os.environ.get('APP_SECRET_KEY')
if not app.secret_key:
    raise RuntimeError('APP_SECRET_KEY environment variable must be set')

# Multi-tenant Solidity container orchestration platform
# Manages isolated compilation/deployment environments per tenant

TENANT_REGISTRY = {
    'tenant_alpha': {'domain': 'alpha.soliditycloud.io', 'tier': 'enterprise'},
    'tenant_beta': {'domain': 'beta.soliditycloud.io', 'tier': 'standard'},
    'tenant_gamma': {'domain': 'gamma.soliditycloud.io', 'tier': 'enterprise'},
}

ALLOWED_REDIRECT_DOMAINS = [
    'soliditycloud.io',
    'auth.soliditycloud.io',
    'dashboard.soliditycloud.io',
]

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'tenant_id' not in session:
            abort(401)
        return f(*args, **kwargs)
    return decorated

def normalize_url(url):
    """Normalize URL to prevent bypass via encoding tricks."""
    # Decode any percent-encoding
    decoded = urllib.parse.unquote(url)
    # Remove any null bytes
    decoded = decoded.replace('\x00', '')
    # Normalize backslashes to forward slashes
    decoded = decoded.replace('\\', '/')
    return decoded

def extract_hostname(url):
    """Extract hostname from URL for validation."""
    try:
        parsed = urllib.parse.urlparse(url)
        hostname = parsed.hostname
        if hostname is None:
            return None
        return hostname.lower()
    except Exception:
        return None

def is_safe_redirect(url):
    """Validate that redirect target is within allowed domains.
    Uses defense-in-depth: normalization + parsing + domain allowlist."""
    if not url:
        return False

    # Step 1: Normalize
    normalized = normalize_url(url)

    # Step 2: Block protocol-relative URLs
    if normalized.startswith('//'):
        return False

    # Step 3: Only allow http/https
    parsed = urllib.parse.urlparse(normalized)
    if parsed.scheme and parsed.scheme not in ('http', 'https'):
        return False

    # Step 4: If it's a relative URL, it's safe
    if not parsed.scheme and not parsed.netloc:
        return True

    # Step 5: Check against allowlist
    hostname = extract_hostname(normalized)
    if hostname is None:
        return False

    # Allow exact matches or subdomains of allowed domains
    for allowed in ALLOWED_REDIRECT_DOMAINS:
        if hostname == allowed or hostname.endswith('.' + allowed):
            return True

    return False

def compute_container_callback(tenant_id, operation, return_url):
    """Generate callback URL for container orchestration events.
    When a Solidity compilation container finishes, it redirects back
    to the orchestrator with results."""
    # Tenant-specific callback routing
    tenant = TENANT_REGISTRY.get(tenant_id)
    if not tenant:
        return None

    # Enterprise tenants can specify custom return URLs for CI/CD integration
    if tenant['tier'] == 'enterprise' and return_url:
        # Validate the return URL
        if is_safe_redirect(return_url):
            return return_url
        # Fall through to default if validation fails

    return f"https://dashboard.soliditycloud.io/{tenant_id}/containers/{operation}"

@app.route('/auth/login', methods=['POST'])
def login():
    tenant_id = request.form.get('tenant_id')
    api_key = request.form.get('api_key')

    if tenant_id not in TENANT_REGISTRY:
        abort(403)

    # In production, validate api_key against secure store
    expected = hmac.new(app.secret_key.encode(), tenant_id.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(api_key or '', expected):
        abort(403)

    session['tenant_id'] = tenant_id
    return jsonify({'status': 'authenticated'})

@app.route('/containers/compile/callback')
@require_auth
def compile_callback():
    """Handle callback after Solidity compilation container completes.
    Redirects user to appropriate results page."""
    tenant_id = session['tenant_id']
    operation = request.args.get('op', 'status')
    next_url = request.args.get('next', '')

    # Sanitize operation parameter
    if not re.match(r'^[a-z_]+$', operation):
        operation = 'status'

    callback_url = compute_container_callback(tenant_id, operation, next_url)

    if callback_url is None:
        abort(400)

    return redirect(callback_url)

@app.route('/containers/deploy/complete')
@require_auth
def deploy_complete():
    """Handle redirect after deployment container finishes.
    Supports cross-tenant notification via signed URLs."""
    tenant_id = session['tenant_id']
    target = request.args.get('target', '')
    sig = request.args.get('sig', '')

    # Verify signature for cross-tenant redirects
    expected_sig = hmac.new(
        app.secret_key.encode(),
        f"{tenant_id}:{target}".encode(),
        hashlib.sha256
    ).hexdigest()[:16]

    if hmac.compare_digest(sig, expected_sig):
        # Signed URL - still validate domain even for signed URLs
        # Defense in depth: signature proves origin but we still enforce allowlist
        if is_safe_redirect(target):
            return redirect(target)

    # Unsigned - must pass domain validation
    if is_safe_redirect(target):
        return redirect(target)

    return redirect(f'https://dashboard.soliditycloud.io/{tenant_id}/deployments')

@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'service': 'container-orchestrator'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
